CREATE TABLE IF NOT EXISTS products (
id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,item_id VARCHAR(100) NOT NULL UNIQUE,shop_id VARCHAR(100),name TEXT,price DECIMAL(15,2),discount_price DECIMAL(15,2),stock_status VARCHAR(30),rating DECIMAL(5,2),sold BIGINT,image_main TEXT,images LONGTEXT,url TEXT,category VARCHAR(255),variations LONGTEXT,scraped_at VARCHAR(50),marketplace VARCHAR(30),active TINYINT(1) DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;